const STYLE_ID = 'chaospad-styles'

const CHAOSPAD_CSS = `
.chaospad-root {
	position: fixed;
	inset: 0;
	z-index: 0;
	width: 100%;
	height: 100%;
	overflow: hidden;
	touch-action: none;
	user-select: none;
	-webkit-user-select: none;
}

.chaospad-root.chaospad-pass-through {
	pointer-events: none;
	touch-action: auto;
	user-select: auto;
	-webkit-user-select: auto;
}

.chaospad-pass-through .chaospad-surface {
	pointer-events: none;
	touch-action: auto;
}

.chaospad-surface {
	position: absolute;
	inset: 0;
	touch-action: none;
}

.chaospad-glow-layer {
	position: absolute;
	inset: 0;
	overflow: hidden;
	pointer-events: none;
	z-index: 1;
}

.chaospad-gl-canvas {
	position: absolute;
	inset: 0;
	display: block;
	pointer-events: none;
}
`

export function injectChaospadStyles() {
	if (typeof document === 'undefined') return
	if (document.getElementById(STYLE_ID)) return

	const style = document.createElement('style')
	style.id = STYLE_ID
	style.textContent = CHAOSPAD_CSS
	document.head.appendChild(style)
}
